    default => sub {
        Net::GitHub::V3->new( maybe ua => $_[0]->api_ua );
    },
);

has api_ua => (
    is => 'ro',
    lazy => 1,
    default => sub { $App::gh::TEST_UA },
);



sub search_repositories {
